                valueListenable: browserController.scrollVisibilityTick,
                builder: (context, _, child) {
                  final playingPath = context.select<PlaybackController, String?>(
                    (player) => player.songInfo?.track.path,
                  );

                  // B-015: show the jump glyph when the playing track lives outside
                  // the browsed folder; B-031 debounces the hide.
                  final isPlaying =
                      context.select<PlaybackController, bool>(
                        (player) => player.isPlaying,
                      );

                  final hasPlaying =
                      isPlaying && playingPath != null && playingPath.isNotEmpty;
                  final currentFolder = path ?? '';
                  final playingParent =
                      hasPlaying ? p.dirname(playingPath) : '';
                  final parentMismatch =
                      hasPlaying && playingParent != currentFolder;

                  // Linux: also show the action when the playing row is scrolled
                  // outside the browser's visible viewport (even if we're already
                  // in the correct folder).
                  final offscreenInFolder = Platform.isLinux &&
                      hasPlaying &&
                      playingParent == currentFolder &&
                      !browserController.isTrackVisible(playingPath);

                  final divergent = hasPlaying && (parentMismatch || offscreenInFolder);
                  final showJumpGlyph = resolveJumpGlyphVisible(divergent);

                  // 12-px vertical padding preserves the crumb baseline; the 44×44
                  // glyph hit target sits outside it (Material min, B-013).
                  return Row(
                    crossAxisAlignment: CrossAxisAlignment.center,
                    children: [
                      Expanded(
                        child: Padding(
                          padding: const EdgeInsets.fromLTRB(20, 12, 0, 12),
                          child: MidEllipsis(
                            text: path == null || path.isEmpty ? '~' : path,
                            style: mono(palette.fgSecondary, typography.crumbSize),
                          ),
                        ),
                      ),
                      if (showJumpGlyph && playingPath != null && isPlaying)
                        buildJumpGlyph(playingPath)
                      else
                        const SizedBox(width: 20),
                    ],
                  );
                },
              );
            },
          ),
        ),
      );
    }

    Widget buildProgressHairline() {
      return Selector<PlaybackController, ({int position, int duration})>(
        selector: (_, player) => (
          position: player.songInfo?.position ?? 0,
          duration: player.songInfo?.duration ?? 0,
        ),
        builder: (context, progress, _) {
          final position = progress.position;
          final duration = progress.duration;
          final fraction = duration <= 0
              ? 0.0
              : (position / duration).clamp(0.0, 1.0);
          return SizedBox(
            height: 1,
            child: Align(
              alignment: Alignment.bottomLeft,
              child: FractionallySizedBox(
                widthFactor: fraction,
                heightFactor: 1,
                child: Container(color: palette.progress),
              ),
            ),
          );
        },
      );

